def check(output, ctx):
    try:
        d = parse_json(output)
        if not isinstance(d, dict):
            return True
        toks = ctx['text'].lower().split()
        spans = set()
        n = len(toks)
        for i in range(n):
            for j in range(i + 1, min(n, i + 60) + 1):
                spans.add(' '.join(toks[i:j]))
        for k, v in d.items():
            if not isinstance(v, list):
                continue
            for e in v:
                if isinstance(e, str):
                    s = e.strip().lower()
                    if s and ' '.join(s.split()) == s and s not in spans:
                        if len(s.split()) <= 60:
                            return False
        return True
    except Exception:
        return True

